  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'토요일'의 영어 단어는?","a":"Saturday","o":["Friday","Sunday","Saturday","Thursday"]},{"q":"'목요일'의 영어 단어는?","a":"Thursday","o":["Wednesday","Tuesday","Sunday","Thursday"]},{"q":"'월요일'의 영어 단어는?","a":"Monday","o":["Tuesday","Sunday","Friday","Monday"]},{"q":"'일요일'의 영어 단어는?","a":"Sunday","o":["Thursday","Wednesday","Sunday","Tuesday"]},{"q":"'화요일'의 영어 단어는?","a":"Tuesday","o":["Monday","Saturday","Sunday","Tuesday"]},{"q":"'금요일'의 영어 단어는?","a":"Friday","o":["Sunday","Tuesday","Wednesday","Friday"]},{"q":"'수요일'의 영어 단어는?","a":"Wednesday","o":["Wednesday","Tuesday","Saturday","Sunday"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
