        if (left <= 0) {
          stop();
          msg.textContent = '쉬는 시간 시간이 끝났어요!';
        }
      }, 1000);
    });

    document.getElementById('reset').addEventListener('click', function () {
      stop();
      left = total;
      timeEl.textContent = left;
      msg.textContent = '';
    });
  </script>
</body>
</html>
