  <style>
    body { font-family: sans-serif; text-align: center; background: #e0f2fe; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
  </style>
</head>
<body>
  <h1>양치 10초 타이머</h1>
  <p id="time" style="font-size: 64px">10</p>
  <button id="start">시작</button>
  <button id="reset">처음으로</button>
  <p id="msg"></p>
  <script>
    const total = 10;
    let left = total;
    let timerId = null;
    const timeEl = document.getElementById('time');
    const msg = document.getElementById('msg');

    function stop() {
      clearInterval(timerId);
      timerId = null;
    }

    document.getElementById('start').addEventListener('click', function () {
      if (timerId) return;
      msg.textContent = '';
      if (left <= 0) left = total;
      timerId = setInterval(function () {
        left -= 1;
        timeEl.textContent = left;
        if (left <= 0) {
          stop();
          msg.textContent = '양치 시간이 끝났어요!';
        }
      }, 1000);
    });

    document.getElementById('reset').addEventListener('click', function () {
      stop();
      left = total;
      timeEl.textContent = left;
      msg.textContent = '';
    });
  </script>
</body>
</html>
