    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #card { font-size: 40px; font-weight: bold; background: #ffffff; border-radius: 16px; padding: 48px 24px; margin: 20px auto; max-width: 320px; box-shadow: 0 4px 12px rgba(0,0,0,.15); }
  </style>
