    const questions = [{"q":"'강아지'의 영어 단어는?","a":"dog","o":["elephant","dog","bear","tiger"]},{"q":"'고양이'의 영어 단어는?","a":"cat","o":["rabbit","pig","cat","tiger"]},{"q":"'곰'의 영어 단어는?","a":"bear","o":["monkey","duck","bear","rabbit"]},{"q":"'돼지'의 영어 단어는?","a":"pig","o":["horse","pig","duck","tiger"]},{"q":"'오리'의 영어 단어는?","a":"duck","o":["horse","duck","dog","tiger"]},{"q":"'호랑이'의 영어 단어는?","a":"tiger","o":["tiger","cat","lion","bear"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
