  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'화요일'의 영어 단어는?","a":"Tuesday","o":["Saturday","Friday","Tuesday","Thursday"]},{"q":"'토요일'의 영어 단어는?","a":"Saturday","o":["Saturday","Sunday","Monday","Friday"]},{"q":"'월요일'의 영어 단어는?","a":"Monday","o":["Sunday","Monday","Wednesday","Friday"]},{"q":"'목요일'의 영어 단어는?","a":"Thursday","o":["Thursday","Sunday","Saturday","Wednesday"]},{"q":"'일요일'의 영어 단어는?","a":"Sunday","o":["Tuesday","Monday","Saturday","Sunday"]},{"q":"'수요일'의 영어 단어는?","a":"Wednesday","o":["Thursday","Monday","Wednesday","Friday"]},{"q":"'금요일'의 영어 단어는?","a":"Friday","o":["Friday","Wednesday","Saturday","Monday"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

    showQuestion();
  </script>
