    const questions = [{"q":"'동생'의 영어 단어는?","a":"younger sibling","o":["grandmother","younger sibling","grandfather","dad"]},{"q":"'할머니'의 영어 단어는?","a":"grandmother","o":["older sister","older brother","younger sibling","grandmother"]},{"q":"'할아버지'의 영어 단어는?","a":"grandfather","o":["younger sibling","mom","grandfather","older brother"]},{"q":"'누나'의 영어 단어는?","a":"older sister","o":["older sister","grandmother","older brother","younger sibling"]},{"q":"'엄마'의 영어 단어는?","a":"mom","o":["mom","dad","older sister","younger sibling"]},{"q":"'아빠'의 영어 단어는?","a":"dad","o":["dad","younger sibling","older sister","mom"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
