  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'말'의 영어 단어는?","a":"horse","o":["giraffe","horse","bear","duck"]},{"q":"'사자'의 영어 단어는?","a":"lion","o":["elephant","lion","bear","duck"]},{"q":"'토끼'의 영어 단어는?","a":"rabbit","o":["lion","elephant","horse","rabbit"]},{"q":"'고양이'의 영어 단어는?","a":"cat","o":["bear","cat","horse","rabbit"]},{"q":"'코끼리'의 영어 단어는?","a":"elephant","o":["horse","elephant","bear","dog"]},{"q":"'원숭이'의 영어 단어는?","a":"monkey","o":["monkey","cat","duck","rabbit"]},{"q":"'곰'의 영어 단어는?","a":"bear","o":["cat","elephant","dog","bear"]},{"q":"'오리'의 영어 단어는?","a":"duck","o":["horse","cat","duck","bear"]},{"q":"'기린'의 영어 단어는?","a":"giraffe","o":["pig","rabbit","giraffe","bear"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

    showQuestion();
  </script>
</body>
</html>
