  <script>
    const questions = [{"q":"'아빠'의 영어 단어는?","a":"dad","o":["dad","younger sibling","mom"]},{"q":"'엄마'의 영어 단어는?","a":"mom","o":["grandfather","younger sibling","mom"]},{"q":"'동생'의 영어 단어는?","a":"younger sibling","o":["younger sibling","grandfather","older brother"]},{"q":"'할아버지'의 영어 단어는?","a":"grandfather","o":["dad","grandfather","mom"]},{"q":"'누나'의 영어 단어는?","a":"older sister","o":["older sister","grandmother","older brother"]},{"q":"'할머니'의 영어 단어는?","a":"grandmother","o":["grandmother","older sister","mom"]},{"q":"'형'의 영어 단어는?","a":"older brother","o":["older sister","grandmother","older brother"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
