<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>영어 요일 퀴즈</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #fff8e1; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
  </style>
</head>
<body>
  <h1>영어 요일 퀴즈</h1>
  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'수요일'의 영어 단어는?","a":"Wednesday","o":["Sunday","Wednesday","Thursday","Monday"]},{"q":"'화요일'의 영어 단어는?","a":"Tuesday","o":["Friday","Wednesday","Thursday","Tuesday"]},{"q":"'월요일'의 영어 단어는?","a":"Monday","o":["Tuesday","Wednesday","Friday","Monday"]},{"q":"'금요일'의 영어 단어는?","a":"Friday","o":["Thursday","Friday","Wednesday","Monday"]},{"q":"'일요일'의 영어 단어는?","a":"Sunday","o":["Thursday","Friday","Sunday","Wednesday"]},{"q":"'목요일'의 영어 단어는?","a":"Thursday","o":["Thursday","Monday","Wednesday","Tuesday"]},{"q":"'토요일'의 영어 단어는?","a":"Saturday","o":["Thursday","Sunday","Saturday","Wednesday"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

    showQuestion();
  </script>
</body>
</html>
