    const questions = [{"q":"오리의 울음소리는?","a":"꽥꽥","o":["꽥꽥","꿀꿀","부엉부엉","멍멍"]},{"q":"닭의 울음소리는?","a":"꼬꼬댁","o":["메에","개굴개굴","짹짹","꼬꼬댁"]},{"q":"양의 울음소리는?","a":"메에","o":["멍멍","어흥","메에","꽥꽥"]},{"q":"사자의 울음소리는?","a":"어흥","o":["음메","짹짹","어흥","멍멍"]},{"q":"병아리의 울음소리는?","a":"삐약삐약","o":["까악까악","삐약삐약","부엉부엉","꽥꽥"]}];
