  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'발'의 영어 단어는?","a":"foot","o":["foot","leg","head"]},{"q":"'팔'의 영어 단어는?","a":"arm","o":["eye","arm","foot"]},{"q":"'귀'의 영어 단어는?","a":"ear","o":["head","ear","hand"]},{"q":"'머리'의 영어 단어는?","a":"head","o":["eye","arm","head"]},{"q":"'다리'의 영어 단어는?","a":"leg","o":["leg","head","ear"]},{"q":"'코'의 영어 단어는?","a":"nose","o":["head","nose","eye"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
