        b.y += b.dy;
        if (b.x < 19 || b.x > canvas.width - 19) b.dx = -b.dx;
        if (b.y < 19 || b.y > canvas.height - 19) b.dy = -b.dy;
        ctx.beginPath();
        ctx.arc(b.x, b.y, 19, 0, Math.PI * 2);
        ctx.fillStyle = '#38bdf8';
        ctx.fill();
      });
      requestAnimationFrame(draw);
    }

    draw();
