  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'코끼리'의 영어 단어는?","a":"elephant","o":["bear","elephant","pig"]},{"q":"'기린'의 영어 단어는?","a":"giraffe","o":["giraffe","tiger","dog"]},{"q":"'곰'의 영어 단어는?","a":"bear","o":["tiger","bear","elephant"]},{"q":"'원숭이'의 영어 단어는?","a":"monkey","o":["lion","tiger","monkey"]},{"q":"'사자'의 영어 단어는?","a":"lion","o":["lion","dog","giraffe"]},{"q":"'고양이'의 영어 단어는?","a":"cat","o":["cat","tiger","rabbit"]},{"q":"'강아지'의 영어 단어는?","a":"dog","o":["dog","duck","rabbit"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
