  <script>
    const questions = [{"q":"'하양'의 영어 단어는?","a":"white","o":["white","yellow","red","orange"]},{"q":"'분홍'의 영어 단어는?","a":"pink","o":["brown","pink","yellow","purple"]},{"q":"'초록'의 영어 단어는?","a":"green","o":["pink","blue","gray","green"]},{"q":"'보라'의 영어 단어는?","a":"purple","o":["purple","orange","brown","green"]},{"q":"'회색'의 영어 단어는?","a":"gray","o":["purple","gray","pink","blue"]},{"q":"'빨강'의 영어 단어는?","a":"red","o":["blue","green","yellow","red"]},{"q":"'주황'의 영어 단어는?","a":"orange","o":["black","blue","pink","orange"]},{"q":"'검정'의 영어 단어는?","a":"black","o":["yellow","black","green","red"]},{"q":"'갈색'의 영어 단어는?","a":"brown","o":["green","brown","red","purple"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
