<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>영어 색깔 퀴즈</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #ffedd5; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
  </style>
</head>
<body>
  <h1>영어 색깔 퀴즈</h1>
  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'갈색'의 영어 단어는?","a":"brown","o":["orange","brown","gray"]},{"q":"'파랑'의 영어 단어는?","a":"blue","o":["purple","gray","blue"]},{"q":"'초록'의 영어 단어는?","a":"green","o":["pink","green","blue"]},{"q":"'보라'의 영어 단어는?","a":"purple","o":["blue","purple","red"]},{"q":"'빨강'의 영어 단어는?","a":"red","o":["pink","red","purple"]},{"q":"'노랑'의 영어 단어는?","a":"yellow","o":["black","pink","yellow"]},{"q":"'분홍'의 영어 단어는?","a":"pink","o":["gray","pink","yellow"]},{"q":"'회색'의 영어 단어는?","a":"gray","o":["pink","gray","white"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

    showQuestion();
  </script>
</body>
</html>
