  <p id="feedback"></p>
  <script>
    const questions = [{"q":"태양에서 2번째로 가까운 행성은?","a":"금성","o":["수성","금성","토성","지구"]},{"q":"태양에서 6번째로 가까운 행성은?","a":"토성","o":["천왕성","지구","수성","토성"]},{"q":"태양에서 1번째로 가까운 행성은?","a":"수성","o":["금성","수성","목성","지구"]},{"q":"태양에서 3번째로 가까운 행성은?","a":"지구","o":["금성","해왕성","토성","지구"]},{"q":"태양에서 7번째로 가까운 행성은?","a":"천왕성","o":["토성","목성","수성","천왕성"]},{"q":"태양에서 5번째로 가까운 행성은?","a":"목성","o":["목성","토성","화성","수성"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
