    const questions = [{"q":"'책'의 영어 단어는?","a":"book","o":["book","chair","bag"]},{"q":"'공책'의 영어 단어는?","a":"notebook","o":["pencil","desk","notebook"]},{"q":"'의자'의 영어 단어는?","a":"chair","o":["chair","ruler","scissors"]},{"q":"'책상'의 영어 단어는?","a":"desk","o":["desk","book","bag"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
