    const questions = [{"q":"'지우개'의 영어 단어는?","a":"eraser","o":["bag","chair","eraser"]},{"q":"'연필'의 영어 단어는?","a":"pencil","o":["pencil","ruler","desk"]},{"q":"'칠판'의 영어 단어는?","a":"blackboard","o":["bag","blackboard","notebook"]},{"q":"'의자'의 영어 단어는?","a":"chair","o":["chair","eraser","bag"]},{"q":"'책'의 영어 단어는?","a":"book","o":["bag","book","desk"]},{"q":"'가방'의 영어 단어는?","a":"bag","o":["bag","scissors","book"]},{"q":"'공책'의 영어 단어는?","a":"notebook","o":["ruler","notebook","desk"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

