    const questions = [{"q":"'갈색'의 영어 단어는?","a":"brown","o":["red","brown","white"]},{"q":"'분홍'의 영어 단어는?","a":"pink","o":["blue","pink","yellow"]},{"q":"'하양'의 영어 단어는?","a":"white","o":["orange","yellow","white"]},{"q":"'주황'의 영어 단어는?","a":"orange","o":["brown","orange","gray"]},{"q":"'노랑'의 영어 단어는?","a":"yellow","o":["yellow","purple","green"]},{"q":"'초록'의 영어 단어는?","a":"green","o":["green","orange","brown"]},{"q":"'회색'의 영어 단어는?","a":"gray","o":["pink","gray","blue"]},{"q":"'검정'의 영어 단어는?","a":"black","o":["black","purple","orange"]}];
    let index = 0;
    let score = 0;
    let answered = false;
