<head>
  <meta charset="UTF-8">
  <title>영어 학용품 카드</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #111827; color: #f9fafb; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #card { font-size: 40px; font-weight: bold; background: #1f2937; border-radius: 16px; padding: 48px 24px; margin: 20px auto; max-width: 320px; box-shadow: 0 4px 12px rgba(0,0,0,.15); }
  </style>
</head>
<body>
  <h1>영어 학용품 카드</h1>
  <div id="card">?</div>
  <p id="count"></p>
  <button id="flip">뒤집기</button>
  <button id="next">다음</button>
  <script>
    const cards = [["칠판","blackboard"],["책상","desk"],["가위","scissors"],["연필","pencil"],["지우개","eraser"],["공책","notebook"],["가방","bag"],["의자","chair"],["책","book"]];
    let index = 0;
    let showBack = false;
    const cardEl = document.getElementById('card');
    const countEl = document.getElementById('count');

    function render() {
      const pair = cards[index];
      cardEl.textContent = showBack ? pair[1] : pair[0];
      countEl.textContent = (index + 1) + ' / ' + cards.length;
    }

    document.getElementById('flip').addEventListener('click', function () {
      showBack = !showBack;
      render();
    });

    document.getElementById('next').addEventListener('click', function () {
      index = (index + 1) % cards.length;
      showBack = false;
      render();
    });

    render();
  </script>
</body>
</html>
