    #card { font-size: 40px; font-weight: bold; background: #ffffff; border-radius: 16px; padding: 48px 24px; margin: 20px auto; max-width: 320px; box-shadow: 0 4px 12px rgba(0,0,0,.15); }
  </style>
</head>
<body>
  <h1>영어 동물 카드</h1>
  <div id="card">?</div>
  <p id="count"></p>
  <button id="flip">뒤집기</button>
  <button id="next">다음</button>
  <script>
    const cards = [["원숭이","monkey"],["코끼리","elephant"],["사자","lion"],["기린","giraffe"],["말","horse"]];
    let index = 0;
    let showBack = false;
    const cardEl = document.getElementById('card');
    const countEl = document.getElementById('count');

    function render() {
      const pair = cards[index];
      cardEl.textContent = showBack ? pair[1] : pair[0];
      countEl.textContent = (index + 1) + ' / ' + cards.length;
    }

    document.getElementById('flip').addEventListener('click', function () {
      showBack = !showBack;
      render();
    });

    document.getElementById('next').addEventListener('click', function () {
      index = (index + 1) % cards.length;
      showBack = false;
      render();
    });

    render();
  </script>
</body>
</html>
