    const questions = [{"q":"'발'의 영어 단어는?","a":"foot","o":["mouth","arm","foot"]},{"q":"'눈'의 영어 단어는?","a":"eye","o":["leg","hand","eye"]},{"q":"'입'의 영어 단어는?","a":"mouth","o":["mouth","ear","head"]},{"q":"'머리'의 영어 단어는?","a":"head","o":["ear","nose","head"]},{"q":"'코'의 영어 단어는?","a":"nose","o":["head","nose","foot"]},{"q":"'귀'의 영어 단어는?","a":"ear","o":["ear","hand","nose"]},{"q":"'팔'의 영어 단어는?","a":"arm","o":["hand","arm","leg"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
