    const questions = [{"q":"'입'의 영어 단어는?","a":"mouth","o":["arm","ear","mouth"]},{"q":"'발'의 영어 단어는?","a":"foot","o":["foot","mouth","head"]},{"q":"'팔'의 영어 단어는?","a":"arm","o":["arm","head","nose"]},{"q":"'손'의 영어 단어는?","a":"hand","o":["nose","mouth","hand"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

