  <canvas id="canvas" width="480" height="320"></canvas>
  <script>
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const balls = [];

    function addBall() {
      balls.push({
        x: Math.random() * (canvas.width - 54) + 27,
        y: Math.random() * (canvas.height - 54) + 27,
        dx: (Math.random() < 0.5 ? -1 : 1) * 7,
        dy: (Math.random() < 0.5 ? -1 : 1) * 7
      });
    }

    for (let i = 0; i < 1; i++) {
      addBall();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      balls.forEach(function (b) {
        b.x += b.dx;
        b.y += b.dy;
        if (b.x < 27 || b.x > canvas.width - 27) b.dx = -b.dx;
        if (b.y < 27 || b.y > canvas.height - 27) b.dy = -b.dy;
        ctx.beginPath();
        ctx.arc(b.x, b.y, 27, 0, Math.PI * 2);
        ctx.fillStyle = '#22c55e';
        ctx.fill();
      });
      requestAnimationFrame(draw);
    }

    draw();
  </script>
</body>
</html>
