  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'의자'의 영어 단어는?","a":"chair","o":["ruler","bag","chair"]},{"q":"'공책'의 영어 단어는?","a":"notebook","o":["scissors","book","notebook"]},{"q":"'지우개'의 영어 단어는?","a":"eraser","o":["blackboard","desk","eraser"]},{"q":"'책'의 영어 단어는?","a":"book","o":["bag","pencil","book"]},{"q":"'가위'의 영어 단어는?","a":"scissors","o":["pencil","scissors","desk"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
