<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>영어 가족 퀴즈</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #f1f5f9; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
  </style>
</head>
<body>
  <h1>영어 가족 퀴즈</h1>
  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'할아버지'의 영어 단어는?","a":"grandfather","o":["dad","grandfather","younger sibling","grandmother"]},{"q":"'할머니'의 영어 단어는?","a":"grandmother","o":["older brother","mom","younger sibling","grandmother"]},{"q":"'엄마'의 영어 단어는?","a":"mom","o":["mom","older sister","younger sibling","dad"]},{"q":"'아빠'의 영어 단어는?","a":"dad","o":["older brother","dad","grandfather","older sister"]},{"q":"'누나'의 영어 단어는?","a":"older sister","o":["grandmother","older sister","older brother","younger sibling"]},{"q":"'동생'의 영어 단어는?","a":"younger sibling","o":["younger sibling","older sister","grandfather","mom"]},{"q":"'형'의 영어 단어는?","a":"older brother","o":["older sister","mom","grandmother","older brother"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

    showQuestion();
  </script>
</body>
</html>
