    const questions = [{"q":"튀르키예의 수도는?","a":"앙카라","o":["서울","베를린","브라질리아","앙카라"]},{"q":"프랑스의 수도는?","a":"파리","o":["파리","하노이","워싱턴","도쿄"]},{"q":"캐나다의 수도는?","a":"오타와","o":["베이징","방콕","오타와","캔버라"]},{"q":"러시아의 수도는?","a":"모스크바","o":["런던","모스크바","아테네","베이징"]},{"q":"일본의 수도는?","a":"도쿄","o":["로마","도쿄","브라질리아","워싱턴"]},{"q":"인도의 수도는?","a":"뉴델리","o":["베를린","로마","뉴델리","마드리드"]}];
