  <style>
    body { font-family: sans-serif; text-align: center; background: #ffedd5; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
  </style>
</head>
<body>
  <h1>km를 마일로 바꾸기</h1>
  <input id="input" type="number" placeholder="km">
  <button id="go">바꾸기</button>
  <h2 id="result"></h2>
  <script>
    const input = document.getElementById('input');
    const result = document.getElementById('result');
    const rate = 0.621371;

    document.getElementById('go').addEventListener('click', function () {
      const value = Number(input.value);
      if (input.value === '' || isNaN(value)) {
        result.textContent = '숫자를 넣어 주세요';
        return;
      }
      const answer = Math.round(value * rate * 100) / 100;
      result.textContent = value + 'km = ' + answer + '마일';
    });
  </script>
</body>
</html>
