        y: Math.random() * (canvas.height - 44) + 22,
        dx: (Math.random() < 0.5 ? -1 : 1) * 2,
        dy: (Math.random() < 0.5 ? -1 : 1) * 2
      });
    }

    for (let i = 0; i < 1; i++) {
      addBall();
    }

    canvas.addEventListener('click', function () {
      addBall();
    });

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      balls.forEach(function (b) {
        b.x += b.dx;
        b.y += b.dy;
        if (b.x < 22 || b.x > canvas.width - 22) b.dx = -b.dx;
        if (b.y < 22 || b.y > canvas.height - 22) b.dy = -b.dy;
        ctx.beginPath();
        ctx.arc(b.x, b.y, 22, 0, Math.PI * 2);
        ctx.fillStyle = '#8b5cf6';
        ctx.fill();
      });
      requestAnimationFrame(draw);
    }

    draw();
