        left -= 1;
        timeEl.textContent = left;
        if (left <= 0) {
          stop();
          msg.textContent = '공부 시간이 끝났어요!';
        }
      }, 1000);
    });

    document.getElementById('reset').addEventListener('click', function () {
      stop();
      left = total;
      timeEl.textContent = left;
      msg.textContent = '';
    });
  </script>
</body>
</html>
