  </style>
</head>
<body>
  <h1>영어 가족 카드</h1>
  <div id="card">?</div>
  <p id="count"></p>
  <button id="flip">뒤집기</button>
  <button id="next">다음</button>
  <script>
    const cards = [["동생","younger sibling"],["아빠","dad"],["할아버지","grandfather"],["할머니","grandmother"],["누나","older sister"]];
    let index = 0;
    let showBack = false;
    const cardEl = document.getElementById('card');
    const countEl = document.getElementById('count');

    function render() {
      const pair = cards[index];
      cardEl.textContent = showBack ? pair[1] : pair[0];
      countEl.textContent = (index + 1) + ' / ' + cards.length;
    }

    document.getElementById('flip').addEventListener('click', function () {
      showBack = !showBack;
      render();
    });

    document.getElementById('next').addEventListener('click', function () {
      index = (index + 1) % cards.length;
      showBack = false;
      render();
    });

    render();
  </script>
